//! Pure, stateless composite scoring logic for market data.
pub mod advanced;pub mod calibration;pub mod explain;pub mod intelligence;pub mod microstructure;pub mod quality;pub mod snapshot;pub mod specialized;mod input;mod signals;mod weights;
pub use advanced::{market_regime,market_structure,volatility,MarketRegime,RegimeResult,StructureResult,StructureState,VolatilityResult,VolatilityState};pub use calibration::{calibrate_confidence,ConfidenceCalibration,PerformanceFeedback};pub use explain::{explain,Explanation};pub use intelligence::{anomaly_zscore,correlation,meta_decision,multi_timeframe,AnomalyResult,AnomalySeverity,CorrelationResult,Decision,MetaDecision,TimeframeResult};pub use microstructure::{derivatives,liquidity_order_flow,DerivativesPressure,DerivativesResult,DominantSide,LiquidityResult};pub use quality::{data_quality,empirical_calibration,risk,signal_quality,AdaptiveWeights,CalibrationResult,ConfidenceLevel,DataQualityResult,DataSourceHealth,RiskLevel,RiskResult,SignalQuality};pub use snapshot::{intelligence_snapshot,IntelligenceSnapshot,SignalComponents};pub use specialized::{cross_market,derivatives_stress,liquidity_sweep,market_shock,regime_transition,signal_conflict,ConflictResult,CrossMarketResult,DerivativesStress,RegimeTransition,ShockResult,SweepResult,SweepSide};pub use input::ScoreInput;pub use weights::{ScoreWeights,SignalReliability};use shared::Score;
pub fn calculate(input:&ScoreInput,weights:&ScoreWeights)->Score{let weights=weights.normalized();let volume_anomaly=signals::volume_anomaly(&input.candles);let funding_extreme=signals::funding_extreme(&input.funding_rate);let order_book_imbalance=signals::order_book_imbalance(&input.order_book);let rsi_divergence=signals::rsi_divergence(&input.candles);let value=volume_anomaly*weights.volume_anomaly+funding_extreme*weights.funding_extreme+order_book_imbalance*weights.order_book_imbalance+rsi_divergence*weights.rsi_divergence;let(symbol,timestamp)=input.candles.last().map(|c|(c.symbol.clone(),c.close_time)).unwrap_or_else(||(input.order_book.symbol.clone(),input.order_book.timestamp));Score{symbol,timestamp,value:value.clamp(0.0,100.0),volume_anomaly,funding_extreme,order_book_imbalance,rsi_divergence}}
#[cfg(test)]mod tests{use super::*;use shared::{Candle,FundingRate,OrderBookLevel,OrderBookSnapshot};fn sample_candles()->Vec<Candle>{(0..40).map(|i|Candle{symbol:"BTCUSDT".into(),interval:"1m".into(),open_time:i*60000,close_time:i*60000+60000,open:100.,high:101.,low:99.,close:100.+i as f64,volume:if i<39{100.}else{500.}}).collect()}fn sample_input()->ScoreInput{ScoreInput{candles:sample_candles(),order_book:OrderBookSnapshot{symbol:"BTCUSDT".into(),timestamp:1000,bids:vec![OrderBookLevel{price:100.,quantity:10.}],asks:vec![OrderBookLevel{price:101.,quantity:10.}]},funding_rate:FundingRate{symbol:"BTCUSDT".into(),timestamp:1000,rate:0.}}}#[test]fn composite_score_is_within_bounds(){let s=calculate(&sample_input(),&ScoreWeights::default());assert!((0.0..=100.0).contains(&s.value));}}
